using LocalPro.Web.Data;using LocalPro.Web.Domain;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;
namespace LocalPro.Web.Pages;public class ServicesModel(AppDbContext db):PageModel{[BindProperty(SupportsGet=true)]public string? Group{get;set;}[BindProperty(SupportsGet=true)]public string? Q{get;set;}public List<Category> Categories{get;set;}=[];public async Task OnGetAsync(){var cats=db.Categories.AsNoTracking().Where(c=>c.Active);if(!string.IsNullOrWhiteSpace(Group))cats=cats.Where(c=>c.Group==Group);if(!string.IsNullOrWhiteSpace(Q))cats=cats.Where(c=>c.Name.Contains(Q)||c.Description.Contains(Q));Categories=await cats.OrderBy(c=>c.SortOrder).ToListAsync();}}
